                row = _validate_row(stream, raw_row, requested_after)
                seq = row["seq"]
                if seq <= previous:
                    raise ValidationError(f"{stream} seq values were not strictly ascending: {seq} after {previous}")
                previous = seq
                validated_batch.append(row)
            if not validated_batch:
                break
            rows.extend(validated_batch)
            requested_after = previous
        return rows

    def _notify_hold(reason: str) -> None:
        message = "HOLD: " + reason.replace("\n", " ").strip()
        status, _ = _request_json("POST", "/owner/notify", {"message": message})
        if not 200 <= status < 300:
            raise RuntimeError(f"owner HOLD notification returned HTTP {status}")

    def _run() -> dict[str, object]:
        logger.info("PHASE read cursors")
        try:
            cursors = _get_required_json("/reports/last")
            expected_cursor_keys = {"orders_last_seq", "refunds_last_seq", "tickets_last_seq"}
            if not isinstance(cursors, dict):
                raise ValidationError(f"cursor response was {type(cursors).__name__}, expected object")
            if set(cursors) != expected_cursor_keys:
                raise ValidationError(
                    f"cursor keys were {sorted(cursors)}, expected exactly {sorted(expected_cursor_keys)}"
                )
            for key in sorted(expected_cursor_keys):
                value = cursors[key]
                if not _is_int(value) or value < 0:
                    raise ValidationError(f"cursor {key} was {value!r}, expected a non-negative integer")

            logger.info("PHASE fetch and validate all stream pages")
            fetched: dict[str, list[dict[str, object]]] = {}
            for stream, spec in stream_specs.items():
                cursor_key = spec["cursor"]
                fetched[stream] = _fetch_stream(stream, cursors[cursor_key])

            counts = {stream: len(rows) for stream, rows in fetched.items()}
            if all(count == 0 for count in counts.values()):
                logger.info("SKIP all three streams were empty")
                return {"status": "skipped", "reason": "all streams empty"}
            if any(count == 0 for count in counts.values()):
                empty = sorted(stream for stream, count in counts.items() if count == 0)
                nonempty = sorted(stream for stream, count in counts.items() if count != 0)
                raise ValidationError(
                    "only some streams had new rows "
                    f"(empty={empty}, nonempty={nonempty}); the required start_seq/end_seq values "
                    "for an empty report section are unspecified, so a correct payload cannot be guaranteed"
                )

            logger.info("PHASE compute exact aggregates")
            order_rows = fetched["orders"]
            refund_rows = fetched["refunds"]
            ticket_rows = fetched["tickets"]
            by_priority = {"low": 0, "normal": 0, "high": 0}
            for row in ticket_rows:
                by_priority[row["priority"]] += 1

            report: dict[str, object] = {
                "orders": {
                    "start_seq": order_rows[0]["seq"],
                    "end_seq": order_rows[-1]["seq"],
                    "count": len(order_rows),
                    "total_units": sum(row["units"] for row in order_rows),
                    "total_revenue_cents": sum(
                        row["units"] * row["unit_price_cents"] for row in order_rows
                    ),
                },
                "refunds": {
                    "start_seq": refund_rows[0]["seq"],
                    "end_seq": refund_rows[-1]["seq"],
                    "count": len(refund_rows),
                    "total_refunded_cents": sum(row["amount_cents"] for row in refund_rows),
                },
                "tickets": {
                    "start_seq": ticket_rows[0]["seq"],
                    "end_seq": ticket_rows[-1]["seq"],
                    "count": len(ticket_rows),
                    "by_priority": by_priority,
                },
            }

            logger.info("PHASE deliver one report")
            try:
                status, _ = _request_json("POST", "/report", report)
            except Exception as exc:
                raise ValidationError(
                    "report POST outcome was uncertain and was not retried to avoid a duplicate: "
                    f"{type(exc).__name__}: {exc}"
                ) from exc
            if not 200 <= status < 300:
                raise ValidationError(f"report POST returned HTTP {status}; delivery was not confirmed and was not retried")
            logger.info("PHASE report delivered")
            return {"status": "delivered", "counts": counts}
        except Exception as exc:
            reason = f"{type(exc).__name__}: {exc}"
            logger.warning("SOFT_FAIL %s", reason)
            try:
                _notify_hold(reason)
            except Exception as notify_exc:
                logger.exception("SOFT_FAIL HOLD notification also failed")
                raise RuntimeError(
                    f"run held because {reason}; HOLD notification failed: {type(notify_exc).__name__}: {notify_exc}"
                ) from notify_exc
            return {"status": "held", "reason": reason}

    return await asyncio.to_thread(_run)
